export function siteRequirement(s,type,x,y,api){const m=api.currentMap(s);if(!DEFENSES[type])return{ok:true};if(type==='antiair'&&!m.buildings.some(b=>ready(b)&&b.type==='radar'&&b.serviceActive))return fail('Necesitas sensores con un operario para esta defensa.');const cells=cellsForSite(m,x,y),survey=surveyFor(m,'defense',cells,api);if(!survey)return fail('Estudia suelo y campo de tiro antes de construir esta defensa.');const heights=cells.map(p=>api.tile(m,p.x,p.y).h);if(Math.max(...heights)-Math.min(...heights)>3)return fail('La plataforma necesita nivelación.');const supplies=m.buildings.filter(b=>ready(b)&&['camp','depot','munitions'].includes(b.type)),supplyDistance=supplies.length?Math.min(...supplies.map(b=>distance(b,{x,y})))*4:10000;let visible=0;for(let n=0;n<16;n++){const angle=n*Math.PI/8;let clear=true;for(let r=1;r<=6;r++){const t=api.tile(m,x+Math.cos(angle)*r,y+Math.sin(angle)*r);if(!t||t.h>api.tile(m,x,y).h+2){clear=false;break;}}if(clear)visible++;}const q=defenseStudy({type:type==='bunker'?'tower':type,slope:(Math.max(...heights)-Math.min(...heights))/24*100,bearing:200,visibility:visible/16*360,supplyDistance,power:api.powered(s,m)?40:0});if(!q.ok)return fail(q.reasons.join(' · '));return{ok:true,surveyId:survey.id,report:q};}
