 if(u.assignment?.task!=='industry')return false;const b=m.buildings.find(b=>b.id===u.assignment.building&&ready(b));if(!b){u.assignment=null;u.order={kind:'hold'};return true;}const needs={...inputFor(b)};for(const r of m.industry.lines.filter(r=>r.a===b.id&&!r.cancelled)){const key=['horse','cart'].includes(r.mode)?'food':r.mode==='train'?'coal':'oil';needs[key]=Math.max(needs[key]||0,4);}const missing=Object.entries(needs).find(([k,v])=>(buildingStore(m,b)[k]||0)<v);if(u.factoryCargo&&Object.values(u.factoryCargo).some(v=>v>0)){if(distance(u,b)>3.5){api.move(m,u,b,dt);return true;}add(buildingStore(m,b),u.factoryCargo);u.factoryCargo={};}else if(missing){const source=m.buildings.filter(v=>ready(v)&&depot(v)).sort((a,c)=>distance(u,a)-distance(u,c))[0],key=missing[0];if(source&&(m.stock[key]||0)>0){if(distance(u,source)>3.5){api.move(m,u,source,dt);u.gatherPhase='return';return true;}const n=Math.min(10,m.stock[key]);m.stock[key]-=n;u.factoryCargo={[key]:n};u.path=null;return true;}}
