export function bridgePassable(m,x,y,spec){if(m.roads?.[y*m.size+x]?.underConstruction&&!spec.flying&&!spec.naval&&(spec.mass||.1)>.2)return false;const id=m.roads?.[y*m.size+x]?.bridgeId;if(!id||spec.naval||spec.flying)return true;const b=m.industry?.bridges.find(b=>b.id===id);return !b||!b.closed&&(spec.mass||.1)<=b.design.vehicle+b.report.capacityPayloadTonnes;}
export function inspectBridge(s,id,repair,api){const m=api.currentMap(s),b=m.industry.bridges.find(b=>b.id===id);if(!b)return fail('Puente desconocido.');if(!repair){b.inspected=s.time;return ok('Inspección: '+Math.round(b.condition*100)+'% · límite total '+(b.design.vehicle+b.report.capacityPayloadTonnes).toFixed(1)+' t.');}if(!facility(m,'maintenance')&&!facility(m,'bridgeyard'))return fail('Construye un depósito de mantenimiento o parque de puentes.');if(!m.units.some(u=>u.hp>0&&api.TROOPS[u.type].civilian&&b.cells.some(c=>distance(u,c)<5)))return fail('Acerca un constructor a la reparación.');const cost={wood:Math.ceil((1-b.condition)*30)+1,parts:s.era>=12?Math.ceil((1-b.condition)*15)+1:0};if(!afford(m.stock,cost))return fail('Faltan materiales de reparación.');pay(m.stock,cost);b.condition=Math.min(1,b.condition+.4);b.closed=b.condition<=.2;return ok('Reparación completada; la carga nominal no ha cambiado.');}
