const SERVICE_INPUTS={firestation:{water:3,parts:1},hangar:{parts:2},shipwright:{parts:2},maintenance:{parts:2,wood:2}};
function inputFor(b){const d=DEFENSES[b.type];return RECIPES[b.type]?.input||(d?.cost?{[d.cost]:d.use*3}:SERVICE_INPUTS[b.type]||{});}
function pathOnNetwork(m,a,b,mode,api){const kinds=mode==='train'?['rail','bridge']:['path','bridge'],queue=[],parents=new Map();for(let y=-3;y<=3;y++)for(let x=-3;x<=3;x++){const xx=a.x+x,yy=a.y+y,t=api.tile(m,xx,yy);if(xx<0||yy<0||xx>=m.size||yy>=m.size||!t||!kinds.includes(t.kind))continue;const key=yy*m.size+xx;if(!parents.has(key)){queue.push({x:xx,y:yy});parents.set(key,null);}}for(let i=0;i<queue.length&&i<16000;i++){const p=queue[i],key=p.y*m.size+p.x;if(distance(p,b)<=4){const path=[];let k=key;while(k!==null){path.push({x:k%m.size+.5,y:Math.floor(k/m.size)+.5});k=parents.get(k);}return path.reverse();}for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy,key=y*m.size+x,t=api.tile(m,x,y);if(x<0||y<0||x>=m.size||y>=m.size||parents.has(key)||!m.fog[key]||!t||!kinds.includes(t.kind)||mode==='truck'&&t.kind==='path'&&m.roads[key]?.grade==='trail')continue;parents.set(key,p.y*m.size+p.x);queue.push({x,y});}}return null;}
function passLine(m,r,api){return r.points.every(p=>{const t=api.tile(m,p.x,p.y),mode=r.mode;if(!t||!m.fog[Math.floor(p.y)*m.size+Math.floor(p.x)])return false;if(mode==='horse'){const id=m.roads[Math.floor(p.y)*m.size+Math.floor(p.x)]?.bridgeId,b=id&&m.industry.bridges.find(b=>b.id===id);return api.passable(m,p.x,p.y,api.TROOPS[r.vehicleType])&&(!b||!b.closed&&r.totalMass<=b.design.vehicle+b.report.capacityPayloadTonnes);}if(mode==='ship')return['water','bridge'].includes(t.kind);if(mode==='plane')return true;if(!['bridge',mode==='train'?'rail':'path'].includes(t.kind))return false;if(mode==='truck'&&t.kind==='path'&&m.roads[Math.floor(p.y)*m.size+Math.floor(p.x)]?.grade==='trail')return false;const id=m.roads[Math.floor(p.y)*m.size+Math.floor(p.x)]?.bridgeId,b=id&&m.industry.bridges.find(b=>b.id===id);return !b||!b.closed&&r.totalMass<=b.design.vehicle+b.report.capacityPayloadTonnes;});}
export function lineQuote(s,aId,bId,vehicleId,resource,amount,api){const m=api.currentMap(s),a=m.buildings.find(v=>v.id===aId&&ready(v)),b=m.buildings.find(v=>v.id===bId&&ready(v)),u=m.units.find(u=>u.id===vehicleId&&u.hp>0&&!u.embarked&&!u.inTransit),v=u&&LOGISTIC_TYPES[u.type];if(!a||!b||a===b||!v||s.routes.some(r=>r.carrier===u.id)||!api.STOCK_NAMES[resource]||!Number.isInteger(amount)||amount<1||amount>v.capacity)return fail('Selecciona origen, destino, vehículo real y una carga dentro de su capacidad.');if(m.industry.lines.some(r=>!r.cancelled&&r.vehicle===u.id))return fail('Ese vehículo ya tiene una ruta.');let points;if(['cart','truck','train'].includes(v.mode))points=pathOnNetwork(m,a,b,v.mode,api);else if(v.mode==='horse'){const pa=landAccess(m,a,b,api),pb=landAccess(m,b,a,api);if(pa&&pb&&distance(pa,pb)<=180){const p=localPath({size:m.size,tile:(x,y)=>api.tile(m,x,y),passable:(x,y,spec)=>api.passable(m,x,y,spec)&&m.fog[Math.floor(y)*m.size+Math.floor(x)]},pa,pb,api.TROOPS[u.type],5000);points=p.reached?[pa,...p.path]:null;}}else if(v.mode==='ship'){if(!['dock','cargoharbor','shipwright'].includes(a.type)||!['dock','cargoharbor','shipwright'].includes(b.type))return fail('El barco requiere terminales costeras.');const pa=waterAccess(m,a,api),pb=waterAccess(m,b,api);points=pa&&pb?waterPath(m,pa,pb,api):null;}else{if(!['airfield','cargoterminal'].includes(a.type)||!['airfield','cargoterminal'].includes(b.type))return fail('El avión requiere pistas o terminales aéreas.');points=roadCells([{x:a.x,y:a.y},{x:b.x,y:b.y}]).map(p=>({x:p.x+.5,y:p.y+.5}));}if(!points?.length)return fail('No existe una conexión continua transitable. Diseña la red o un itinerario de hasta 180 casillas.');const totalMass=v.mass+amount*(RESOURCE_MASS[resource]||.015),r={mode:v.mode,points,vehicleType:u.type,totalMass};if(!passLine(m,r,api))return fail('La red está cortada, sin explorar o supera la carga de un puente.');const studied=['horse'].includes(v.mode)||surveyFor(m,'corridor',points.map(p=>({x:Math.floor(p.x),y:Math.floor(p.y)})),api)||points.every(p=>{const rr=m.roads[Math.floor(p.y)*m.size+Math.floor(p.x)];return rr?.surveyId||m.industry.projects.some(j=>j.done&&j.steps.some(c=>c.x===Math.floor(p.x)&&c.y===Math.floor(p.y)));});return{ok:true,...r,a:a.id,b:b.id,vehicle:u.id,resource,amount,studied:!!studied,distance:points.length*4};}
export function createLine(s,a,b,vehicle,resource,amount,api){const m=api.currentMap(s),q=lineQuote(s,a,b,vehicle,resource,amount,api);if(!q.ok)return q;if(!q.studied)return fail('Estudia el corredor antes de autorizar esta ruta.');if(m.industry.lines.filter(r=>!r.cancelled).length>=64)return fail('Límite de 64 rutas locales.');const u=m.units.find(v=>v.id===vehicle);m.industry.lines=m.industry.lines.filter(r=>!r.cancelled);m.industry.lines.push({...q,id:'line'+s.serial++,cursor:0,phase:'loading',cargo:0,delivered:0,lost:0,clock:0,status:'Preparando carga',cancelled:false,paused:false});u.assignment=null;u.order={kind:'logistics',target:m.industry.lines.at(-1).id};u.path=null;return ok('Ruta abierta. El vehículo recoge, transporta, entrega y regresa.');}
function waterAccess(m,b,api){for(let r=1;r<=6;r++)for(let x=-r;x<=r;x++)for(let y=-r;y<=r;y++){const p={x:b.x+x+.5,y:b.y+y+.5};if(m.fog[Math.floor(p.y)*m.size+Math.floor(p.x)]&&api.tile(m,p.x,p.y)?.kind==='water')return p;}return null;}
function waterPath(m,a,b,api){const queue=[a],parents=new Map([[Math.floor(a.y)*m.size+Math.floor(a.x),null]]);for(let i=0;i<queue.length&&i<12000;i++){const p=queue[i],key=Math.floor(p.y)*m.size+Math.floor(p.x);if(distance(p,b)<1.5){const path=[];let k=key;while(k!==null){path.push({x:k%m.size+.5,y:Math.floor(k/m.size)+.5});k=parents.get(k);}return path.reverse();}for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=Math.floor(p.x)+dx,y=Math.floor(p.y)+dy,key=y*m.size+x;if(parents.has(key)||x<0||y<0||x>=m.size||y>=m.size||!m.fog[key]||!['water','bridge'].includes(api.tile(m,x,y)?.kind))continue;parents.set(key,Math.floor(p.y)*m.size+Math.floor(p.x));queue.push({x:x+.5,y:y+.5});}}return null;}
function controlConvoy(s,m,u,dt,api){const r=m.industry.lines.find(r=>r.id===u.order.target&&!r.cancelled);if(!r){u.order={kind:'hold'};return true;}if(r.paused){u.walking=false;return true;}const a=m.buildings.find(v=>v.id===r.a&&ready(v)),b=m.buildings.find(v=>v.id===r.b&&ready(v));if(!a||!b){r.status='Terminal destruida';return true;}if(r.checkedRevision!==m.terrain.revision||r.checkedAt===undefined||s.time-r.checkedAt>2){r.checkedRevision=m.terrain.revision;r.checkedAt=s.time;r.passable=passLine(m,r,api);}if(!r.passable){r.status='Ruta bloqueada o puente cerrado';return true;}if(r.phase==='loading'){const point=r.points[0];if(distance(u,point)>1){api.move(m,u,point,dt);return true;}r.clock+=dt;const cooldown=facility(m,'signal')?.serviceActive?4:8;if(r.clock<cooldown)return true;const source=buildingStore(m,a),fuel=['horse','cart'].includes(r.mode)?'food':r.mode==='train'?'coal':'oil',fuelCost=facility(m,'fueltank')?.serviceActive?1:2;if((source[r.resource]||0)<r.amount+(fuel===r.resource?fuelCost:0)||(source[fuel]||0)<fuelCost){r.status='Esperando carga y '+api.STOCK_NAMES[fuel];return true;}source[r.resource]-=r.amount;source[fuel]-=fuelCost;r.cargo=r.amount;r.phase='out';r.cursor=0;r.clock=0;r.status='En viaje';}const target=r.phase==='back'?r.points[Math.max(0,r.cursor)]:r.points[Math.min(r.points.length-1,r.cursor)];if(distance(u,target)>.65){api.move(m,u,target,dt,{...api.unitSpec(s,u),mass:r.totalMass});return true;}const bridgeId=m.roads[Math.floor(target.y)*m.size+Math.floor(target.x)]?.bridgeId;if(bridgeId){const bridge=m.industry.bridges.find(b=>b.id===bridgeId);if(bridge){bridge.crossings++;bridge.condition=Math.max(0,bridge.condition-1/Math.max(1000,bridge.report.lifeYears*bridge.design.traffic*365));}}
 if(r.phase==='out'){r.cursor++;if(r.cursor>=r.points.length){add(buildingStore(m,b),{[r.resource]:r.cargo});r.delivered+=r.cargo;r.cargo=0;r.phase='back';r.cursor=r.points.length-1;r.status='Regresando vacío';}}else if(r.phase==='back'){r.cursor--;if(r.cursor<0){r.cursor=0;r.phase='loading';r.status='Esperando carga';}}return true;}
export function lineAction(s,id,action,api){const m=api.currentMap(s),r=m.industry.lines.find(r=>r.id===id&&!r.cancelled),u=r&&m.units.find(u=>u.id===r.vehicle&&u.hp>0);if(!r)return fail('Ruta desconocida.');if(action==='cancel'){if(r.cargo)return fail('La carga sigue en el vehículo. Completa la entrega o pausa la ruta.');r.cancelled=true;if(u)u.order={kind:'hold'};return ok('Ruta retirada; vehículo disponible.');}if(!u)return fail('El vehículo fue destruido. Crea una ruta con otro vehículo.');r.paused=action==='pause';r.status=r.paused?'Pausada':'Reanudando';if(!r.paused){u.order={kind:'logistics',target:r.id};u.path=null;}return ok(r.status);}
export function resolvePerson(s,id,choice,api){const m=api.currentMap(s),p=m.industry.people.find(p=>p.id===id),role=p&&NPC_ROLES[p.role];if(!role||s.time<p.available)return fail('Este encargo ya está resuelto; espera una nueva visita.');if(!['help','deny'].includes(choice))return fail('Decisión desconocida.');if(choice==='help'){if(!afford(m.stock,role.cost))return fail('Faltan bienes entregados para ayudar.');let spawn;if(p.role==='refugee'){if(api.population(m)>=api.capacity(m))return fail('Necesitas plazas de población.');spawn=freePlace(m,p,api);if(!spawn)return fail('No hay espacio para acoger a la familia.');}pay(m.stock,role.cost);m.stock.credits+=role.reward;ethics(s,role.morale,'Ayuda a '+role.name);if(spawn)m.units.push(api.makeUnit(s,'settler',spawn.x,spawn.y));if(p.role==='medic')for(const u of m.units)if(u.hp>0&&distance(u,p)<8)u.hp=Math.min(u.maxHp,u.hp+15);}else ethics(s,-2,'Negaste ayuda a '+role.name);p.available=s.time+1200;p.completed=(p.completed||0)+1;return ok(choice==='help'?'Encargo cumplido y pago recibido.':'Decisión registrada.');}
function freePlace(m,b,api){for(let r=3;r<7;r++)for(let x=-r;x<=r;x++)for(let y=-r;y<=r;y++)if(api.passable(m,b.x+x,b.y+y,api.TROOPS.settler))return{x:b.x+x+.5,y:b.y+y+.5};return null;}
export function personActors(m){return(m.industry?.people||[]).map(p=>({...p,type:'settler',npcRole:p.role,hp:90,maxHp:90,depth:0,technology:0,training:1,species:'human',bag:{},order:{kind:'hold'}}));}
export function damageTarget(m,target,damage){const protectedBy=m.buildings.find(b=>ready(b)&&b.type==='shield'&&b.serviceActive&&distance(b,target)<DEFENSES.shield.range);target.hp=Math.max(0,target.hp-damage*(protectedBy?.65:1));}
function sourceNode(m,b,resource,api){if(b.type==='fishery'){for(let y=-6;y<=6;y++)for(let x=-6;x<=6;x++){const xx=b.x+x,yy=b.y+y;if(m.fog[yy*m.size+xx]&&api.tile(m,xx,yy)?.kind==='water'){const id='fish:'+xx+':'+yy,amount=Math.max(0,120-(m.depleted[id]||0));if(amount>0)return{id,amount};}}return null;}for(let y=-6;y<=6;y++)for(let x=-6;x<=6;x++){const xx=b.x+x,yy=b.y+y;if(!m.fog[yy*m.size+xx])continue;const node=api.resourceAt(m,xx,yy);if(node?.resource===resource&&!node.renewable&&node.amount>0)return node;}return null;}
function produce(s,m,b,dt,api){b.store??={};const workers=working(m,b);b.serviceActive=workers.length>0;b.status=workers.length?'Operativa':'Sin operarios';const r=RECIPES[b.type];if(!r||!workers.length)return;const power=!r.power||api.powered(s,m);if(!power){b.status='Sin energía';return;}if(!afford(b.store,r.input||{})){b.status='Esperando insumos';return;}if(Object.values(b.store).some(v=>v>=10000)){b.status='Almacén local lleno';return;}let node=r.source&&sourceNode(m,b,r.source,api);if(r.source&&!node){b.status='Recurso local agotado';return;}b.production=(b.production||0)+dt*workers.length*buildingStats(b,api.STRUCTURES[b.type]).output;for(let batch=0;batch<64&&b.production>=r.seconds;batch++){if(!afford(b.store,r.input||{}))break;if(r.source){node=sourceNode(m,b,r.source,api);if(!node)break;}b.production-=r.seconds;pay(b.store,r.input||{});if(node){const amount=Math.min(node.amount,3);m.depleted[node.id]=(m.depleted[node.id]||0)+amount;add(b.store,Object.fromEntries(Object.entries(r.output).map(([k,v])=>[k,v*amount/3])));}else add(b.store,r.output);}}
function serviceStep(s,m,b,dt,api){if(!b.serviceActive)return;const store=b.store,consume=(key,n)=>{if((store[key]||0)<n)return false;store[key]-=n;return true;};if(b.type==='hangar'&&!api.powered(s,m))return;if(['clinic','hangar','shipwright'].includes(b.type)){for(const u of m.units.filter(u=>u.hp>0&&!u.inTransit&&u.hp<u.maxHp&&distance(u,b)<7)){if(b.type==='hangar'&&!api.TROOPS[u.type].flying||b.type==='shipwright'&&!api.TROOPS[u.type].naval)continue;const key=b.type==='clinic'?'medicine':'parts';if(consume(key,dt*.02))u.hp=Math.min(u.maxHp,u.hp+dt*.8*buildingStats(b,api.STRUCTURES[b.type]).output);}}if(b.type==='sewage'&&api.powered(s,m))m.city.pollution=Math.max(0,m.city.pollution-dt*.02);if(b.type==='firestation')for(const target of m.buildings.filter(t=>ready(t)&&t.hp<buildingStats(t,api.STRUCTURES[t.type]).hp&&distance(t,b)<10&&pathOnNetwork(m,b,t,'cart',api)))if((store.water||0)>=dt*.03&&(store.parts||0)>=dt*.005&&consume('water',dt*.03)&&consume('parts',dt*.005))target.hp=Math.min(buildingStats(target,api.STRUCTURES[target.type]).hp,target.hp+dt*.5);}
function defenseStep(s,m,dt,shots,api){for(const b of m.buildings.filter(b=>ready(b)&&DEFENSES[b.type]&&(!b.legacyEngineering||b.type!=='tower'))){const d=DEFENSES[b.type];if(!working(m,b).length||b.type==='antiair'&&!m.buildings.some(v=>ready(v)&&v.type==='radar'&&v.serviceActive)||d.power&&!api.powered(s,m)){b.serviceActive=false;continue;}b.serviceActive=true;if(d.shield)continue;b.cooldown=Math.max(0,(b.cooldown||0)-dt);if(b.cooldown||!afford(b.store||{},{[d.cost]:d.use}))continue;const target=m.enemies.find(e=>e.hp>0&&distance(e,b)<d.range&&m.sight?.[Math.floor(e.y)*m.size+Math.floor(e.x)]&&(d.target==='air'?api.TROOPS[e.type].flying:d.target==='naval'?api.TROOPS[e.type].naval:!api.TROOPS[e.type].flying&&!api.TROOPS[e.type].naval));if(!target)continue;const length=Math.ceil(distance(target,b)),origin=api.tile(m,b.x,b.y).h+2;let blocked=false;for(let i=1;i<length;i++){const t=api.tile(m,b.x+(target.x-b.x)*i/length,b.y+(target.y-b.y)*i/length);if(t?.h>origin){blocked=true;break;}}if(blocked)continue;pay(b.store,{[d.cost]:d.use});target.hp=Math.max(0,target.hp-d.damage*buildingStats(b,api.STRUCTURES[b.type]).output);if(d.splash)for(const e of m.enemies)if(e!==target&&distance(e,target)<d.splash)e.hp=Math.max(0,e.hp-d.damage*.35);shots.push({x:b.x,y:b.y,tx:target.x,ty:target.y,kind:'missile'});b.cooldown=2;}}
export function step(s,m,dt,shots,api,active=true){initMap(m);for(const line of m.industry.lines){const u=m.units.find(u=>u.id===line.vehicle&&u.hp>0);if(!u&&!line.cancelled){line.lost+=line.cargo;line.cargo=0;line.status='Vehículo destruido';line.paused=true;}}
 for(const b of m.industry.bridges){b.condition=Math.max(0,b.condition-dt/(Math.max(1,b.report.lifeYears)*36000));if(s.events.some(e=>e.map===m.id&&['quake','tsunami','tornado'].includes(e.type)&&e.starts<=s.time&&e.ends>s.time&&b.cells.some(p=>distance(p,e)<e.radius)))b.condition=Math.max(0,b.condition-dt*.002);b.closed=b.condition<=.2;}
 m.industry.clock+=dt;if(m.industry.clock>=1){const seconds=m.industry.clock;m.industry.clock=0;for(const b of m.buildings.filter(ready)){b.store??={};if(api.STRUCTURES[b.type].expansion||DEFENSES[b.type]){produce(s,m,b,seconds,api);serviceStep(s,m,b,seconds,api);}}for(const u of m.units.filter(u=>u.type==='medic'&&u.hp>0&&!u.inTransit))for(const v of m.units.filter(v=>v.hp>0&&v.hp<v.maxHp&&distance(u,v)<6))if(m.stock.medicine>=seconds*.01){m.stock.medicine-=seconds*.01;v.hp=Math.min(v.maxHp,v.hp+seconds*.3);}
 if(active&&s.time>=m.industry.nextPeople){m.industry.nextPeople=s.time+30;for(const[role,def]of Object.entries(NPC_ROLES)){const home=facility(m,def.home);if(!home||m.industry.people.some(p=>p.role===role))continue;const place=freePlace(m,home,api);if(place)m.industry.people.push({id:'person'+s.serial++,role,home:home.id,...place,available:s.time,completed:0});}}
 }
 if(active){defenseStep(s,m,dt,shots,api);const people=m.industry.people;if(people.length){const index=Math.floor(s.time*2)%people.length,p=people[index],home=m.buildings.find(b=>b.id===p.home&&ready(b));if(home){const target={x:home.x+Math.sin(s.time/30+index)*4,y:home.y+Math.cos(s.time/30+index)*4};if(api.passable(m,target.x,target.y,api.TROOPS.settler))api.move(m,p,target,dt,api.TROOPS.settler);}}}
}
export function validate(s,api){if(s.systemsVersion!==1)throw Error('Sistemas de campaña inválidos.');const id=v=>typeof v==='string'&&/^[a-z0-9:_-]{1,100}$/i.test(v),coord=(p,m)=>p&&positive(p.x,m.size-1)&&positive(p.y,m.size-1),stock=v=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.entries(v).every(([k,n])=>api.STOCK_NAMES[k]&&positive(n,1e9));for(const m of Object.values(s.maps)){const i=m.industry;if(!i||!Array.isArray(i.surveys)||i.surveys.length>128||!Array.isArray(i.projects)||i.projects.length>64||!Array.isArray(i.bridges)||i.bridges.length>256||!Array.isArray(i.lines)||i.lines.length>64||!Array.isArray(i.people)||i.people.length>12||!positive(i.clock,31)||!positive(i.nextPeople))throw Error('Infraestructura de campaña inválida.');for(const b of m.buildings)if(b.store&&!stock(b.store)||b.species&&!api.SPECIES[b.species]||b.production!==undefined&&!positive(b.production))throw Error('Inventario local inválido.');for(const u of m.units)if(u.factoryCargo&&!stock(u.factoryCargo))throw Error('Carga de operario inválida.');for(const j of i.surveys)if(!id(j.id)||!['site','defense','corridor','passage'].includes(j.kind)||!Array.isArray(j.cells)||j.cells.length>180||j.cells.some(p=>!coord(p,m))||!Number.isInteger(j.index)||j.index<0||j.index>j.cells.length||!positive(j.duration)||!positive(j.elapsed)||!Number.isInteger(j.fingerprint)||typeof j.done!=='boolean')throw Error('Estudio inválido.');for(const p of i.projects)if(!id(p.id)||!Array.isArray(p.steps)||!p.steps.length||p.steps.length>180||p.steps.some(v=>!coord(v,m)||!['path','rail','bridge'].includes(v.kind)||!Number.isInteger(v.h)||!positive(v.h,20))||!Number.isInteger(p.index)||p.index<0||p.index>p.steps.length||!stock(p.cost)||!positive(p.duration)||!positive(p.elapsed)||!api.ROAD_GRADES[p.grade]||!Array.isArray(p.bridges))throw Error('Proyecto inválido.');for(const b of i.bridges){if(!id(b.id)||!Array.isArray(b.cells)||!b.cells.length||b.cells.length>180||b.cells.some(p=>!coord(p,m))||!positive(b.condition,1))throw Error('Puente inválido.');const computed=bridgeEstimate(b.design);if(!computed.ok)throw Error('Diseño de puente no apto.');b.report=computed;if(!positive(b.report?.lifeYears)||!positive(b.report?.capacityPayloadTonnes)||!positive(b.crossings))throw Error('Capacidad de puente inválida.');}for(const r of i.lines)if(!id(r.id)||!['horse','cart','truck','train','ship','plane'].includes(r.mode)||!LOGISTIC_TYPES[r.vehicleType]||!api.STOCK_NAMES[r.resource]||!Number.isInteger(r.amount)||!positive(r.amount,500)||r.amount<1||!positive(r.totalMass,2000)||!positive(r.cargo,r.amount)||!positive(r.delivered)||!positive(r.lost)||!Array.isArray(r.points)||!r.points.length||r.points.length>16000||r.points.some(p=>!coord(p,m))||!Number.isInteger(r.cursor)||r.cursor<0||r.cursor>r.points.length||!['loading','out','back'].includes(r.phase))throw Error('Convoy inválido.');for(const p of i.people)if(!id(p.id)||!NPC_ROLES[p.role]||!coord(p,m)||!positive(p.available)||!positive(p.completed))throw Error('Habitante NPC inválido.');if(i.training&&(!Array.isArray(i.training)||i.training.length>2000))throw Error('Cola de equipo inválida.');for(const j of i.training||[])if(!id(j.unit)||!id(j.facility)||!Number.isInteger(j.level)||j.level<1||j.level>10||!positive(j.duration)||!positive(j.elapsed))throw Error('Entrenamiento inválido.');}}

export function surveyRoute(s,a,b,vehicle,resource,amount,api){const m=api.currentMap(s),q=lineQuote(s,a,b,vehicle,resource,amount,api);if(!q.ok)return q;return startSurvey(s,m,'corridor',q.points.map(p=>({x:Math.floor(p.x),y:Math.floor(p.y)})),[],api);}

function landAccess(m,b,toward,api){const size=api.STRUCTURES[b.type].size,list=[];for(let x=b.x-1;x<=b.x+size;x++)for(let y=b.y-1;y<=b.y+size;y++)if(m.fog[y*m.size+x]&&api.passable(m,x,y,api.TROOPS.packhorse))list.push({x:x+.5,y:y+.5});return list.sort((a,b)=>distance(a,toward)-distance(b,toward))[0];}
export function collectStore(s,id,ids,api){const m=api.currentMap(s),b=m.buildings.find(b=>b.id===id&&ready(b));if(!b||depot(b)||!Object.values(buildingStore(m,b)).some(n=>n>0))return fail('No hay producción local para recoger.');const u=freeWorker(m,api,b,ids);if(!u||api.TROOPS[u.type].naval)return fail('Libera un colono para recoger la carga.');u.assignment=null;u.order={kind:'haul',target:id};u.path=null;return ok('El colono recogerá hasta 10 bienes y los llevará al punto de entrega.');}

export const hasSiteStudy=(m,b,api)=>!!surveyFor(m,'site',cellsForSite(m,b.x,b.y),api);
export function surveyTerminal(s,kind,api){const m=api.currentMap(s),b=facility(m,kind==='air'?'airfield':'dock');return b?surveySite(s,b.x,b.y,'site',[],api):fail('Construye la terminal primero.');}
